/**
 * StorageService 2.0 - Powered by Supabase
 * Handles all cloud database operations for vaults and their associated image streams.
 */
export const StorageService = {

  async createVault(params: {
    username: string;
    vaultName: string;
    pinHash: string;
    expiry: ExpiryOption;
  }): Promise<Vault> {
    const { data, error } = await supabase
      .from('vaults')
      .insert([
        {
          username: params.username,
          vault_name: params.vaultName,
          pin_hash: params.pinHash,
          expiry: params.expiry,
          images: [],
          is_emergency_locked: false,
          failed_attempts: 0,
          is_view_only: false
        }
      ])
      .select()
      .single();

    if (error) {
      if (error.code === '23505') throw new Error('Username already claimed by another agent.');
      throw new Error(error.message);
    }

    return this._mapVault(data);
  },

  async getVaultByUsername(username: string): Promise<Vault | null> {
    const { data, error } = await supabase
      .from('vaults')
      .select('*')
      .eq('username', username)
      .maybeSingle();

    if (error) throw error;
    return data ? this._mapVault(data) : null;
  },

  async getVaultById(id: string): Promise<Vault | null> {
    const { data, error } = await supabase
      .from('vaults')
      .select('*')
      .eq('id', id)
      .maybeSingle();

    if (error) throw error;
    return data ? this._mapVault(data) : null;
  },

  async updateVaultImages(id: string, images: VaultImage[]): Promise<Vault> {
    const { data, error } = await supabase
      .from('vaults')
      .update({ images })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return this._mapVault(data);
  },

  async updateVaultSettings(id: string, updates: Partial<Vault>): Promise<Vault> {
    // Map camelCase to snake_case for Supabase
    const dbUpdates: any = {};
    if (updates.vaultName !== undefined) dbUpdates.vault_name = updates.vaultName;
    if (updates.isEmergencyLocked !== undefined) dbUpdates.is_emergency_locked = updates.isEmergencyLocked;
    if (updates.isViewOnly !== undefined) dbUpdates.is_view_only = updates.isViewOnly;
    if (updates.failedAttempts !== undefined) dbUpdates.failed_attempts = updates.failedAttempts;

    const { data, error } = await supabase
      .from('vaults')
      .update(dbUpdates)
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return this._mapVault(data);
  },

  async incrementFailedAttempts(id: string): Promise<number> {
    const vault = await this.getVaultById(id);
    if (!vault) return 0;

    const newAttempts = vault.failedAttempts + 1;
    const isLocked = newAttempts >= 5;

    const { data, error } = await supabase
      .from('vaults')
      .update({ 
        failed_attempts: newAttempts,
        is_emergency_locked: isLocked
      })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;
    return data.failed_attempts;
  },

  async resetFailedAttempts(id: string) {
    const { error } = await supabase
      .from('vaults')
      .update({ failed_attempts: 0 })
      .eq('id', id);

    if (error) throw error;
  },

  async deleteVault(id: string) {
    const { error } = await supabase
      .from('vaults')
      .delete()
      .eq('id', id);

    if (error) throw error;
  },

  /**
   * Internal mapper to bridge DB schema with app interfaces.
   */
  _mapVault(dbVault: any): Vault {
    return {
      id: dbVault.id,
      username: dbVault.username,
      vaultName: dbVault.vault_name,
      pinHash: dbVault.pin_hash,
      images: dbVault.images || [],
      createdAt: new Date(dbVault.created_at).getTime(),
      expiry: dbVault.expiry as ExpiryOption,
      isEmergencyLocked: dbVault.is_emergency_locked,
      failedAttempts: dbVault.failed_attempts,
      isViewOnly: dbVault.is_view_only
    };
  }
};

import { TG_BOT_TOKEN, TG_CHAT_ID } from '../constants.tsx';

/**
 * Service to handle image interaction with Telegram.
 * SnapSave uses Telegram as an encrypted, distributed storage layer.
 */
export const TelegramService = {
  /**
   * Uploads a file to a Telegram chat via the Bot API.
   * Returns metadata including the file_id.
   */
  async uploadImage(file: File, onProgress?: (percent: number) => void): Promise<{ file_id: string }> {
    return new Promise((resolve, reject) => {
      const formData = new FormData();
      formData.append('chat_id', TG_CHAT_ID);
      formData.append('document', file);

      const xhr = new XMLHttpRequest();
      xhr.open('POST', `https://api.telegram.org/bot${TG_BOT_TOKEN}/sendDocument`, true);

      if (onProgress) {
        xhr.upload.onprogress = (event) => {
          if (event.lengthComputable) {
            const percentComplete = (event.loaded / event.total) * 100;
            onProgress(percentComplete);
          }
        };
      }

      xhr.onload = () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          try {
            const data = JSON.parse(xhr.responseText);
            if (data.ok) {
              const fileId = data.result.document.file_id;
              resolve({ file_id: fileId });
            } else {
              reject(new Error(data.description || 'Telegram upload failed'));
            }
          } catch (e) {
            reject(new Error('Invalid response from Telegram server'));
          }
        } else {
          reject(new Error(`HTTP Error: ${xhr.status} - ${xhr.statusText}`));
        }
      };

      xhr.onerror = () => reject(new Error('Network connection error during Telegram upload'));
      xhr.send(formData);
    });
  },

  /**
   * Resolves a Telegram file_id to a temporary download URL.
   * Telegram file paths are short-lived, so we fetch them on-demand.
   */
  async getImageUrl(fileId: string): Promise<string> {
    try {
      const response = await fetch(`https://api.telegram.org/bot${TG_BOT_TOKEN}/getFile?file_id=${fileId}`);
      const data = await response.json();

      if (data.ok) {
        const filePath = data.result.file_path;
        return `https://api.telegram.org/file/bot${TG_BOT_TOKEN}/${filePath}`;
      }
      return '';
    } catch (error) {
      console.error('Failed to resolve Telegram image path:', error);
      return '';
    }
  }
};

import React, { useState, useEffect } from 'react';
import { Download, Trash2, FileText, Check, Copy, ExternalLink, Shield, Loader2 } from 'lucide-react';
import { VaultImage } from '../types.ts';
import { TelegramService } from '../services/telegramService.ts';

interface ImageCardProps {
  image: VaultImage;
  isViewOnly: boolean;
  onDelete: () => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ image, isViewOnly, onDelete }) => {
  const [displayUrl, setDisplayUrl] = useState<string>(image.url);
  const [resolving, setResolving] = useState<boolean>(false);
  const [copied, setCopied] = useState(false);

  // Cross-device hydration: If the URL is a local blob (from a different device/session)
  // or empty, we fetch the actual Telegram link.
  useEffect(() => {
    const hydrateImage = async () => {
      const isLocalBlob = displayUrl.startsWith('blob:');

      // If it's a blob, check if it's still valid in THIS session
      if (isLocalBlob) {
        try {
          const res = await fetch(displayUrl, { method: 'HEAD' });
          if (res.ok) return; // Local blob is still alive
        } catch (e) {
          // Blob expired or from another device
        }
      }

      // If we got here, we need to fetch a fresh URL from Telegram
      setResolving(true);
      const cloudUrl = await TelegramService.getImageUrl(image.telegramFileId);
      if (cloudUrl) {
        setDisplayUrl(cloudUrl);
      }
      setResolving(false);
    };

    hydrateImage();
  }, [image.telegramFileId]);

  const formatSize = (bytes: number) => {
    if (bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
  };

  const handleDownload = () => {
    if (isViewOnly || !displayUrl) return;
    const a = document.createElement('a');
    a.href = displayUrl;
    a.download = image.name;
    a.click();
  };

  const handleCopy = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (!displayUrl) return;
    navigator.clipboard.writeText(displayUrl);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="group relative glass-card rounded-[2rem] overflow-hidden border-white/5 bg-slate-900/40 hover:shadow-[0_20px_50px_-20px_rgba(99,102,241,0.3)] transition-all duration-500 animate-in fade-in zoom-in-95">
      {/* Security Shield Badge */}
      <div className="absolute top-4 left-4 z-20 opacity-0 group-hover:opacity-100 transition-opacity">
        <div className="p-2 bg-slate-950/80 backdrop-blur-md rounded-xl border border-white/10 text-indigo-400">
            <Shield className="w-3.5 h-3.5" />
        </div>
      </div>

      {/* Image Preview Engine */}
      <div className="aspect-square w-full overflow-hidden bg-slate-950 relative flex items-center justify-center">
        {resolving ? (
          <div className="flex flex-col items-center gap-3">
            <Loader2 className="w-8 h-8 text-indigo-500 animate-spin" />
            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Hydrating Snap...</span>
          </div>
        ) : (
          <img 
            src={displayUrl || 'https://via.placeholder.com/400?text=Stream+Interrupted'} 
            alt={image.name} 
            className="w-full h-full object-cover transition-all duration-1000 group-hover:scale-110 group-hover:rotate-1"
          />
        )}

        {/* Elite Overlay Interface */}
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent opacity-0 group-hover:opacity-100 transition-all duration-500 flex flex-col justify-end p-6">
          {!resolving && (
            <div className="flex items-center justify-center gap-3 translate-y-4 group-hover:translate-y-0 transition-transform duration-500">
              {!isViewOnly && (
                <button 
                  onClick={handleDownload}
                  className="p-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl backdrop-blur-xl border border-white/10 transition-all hover:scale-110 active:scale-95 shadow-2xl"
                  title="Download Stream"
                >
                  <Download className="w-5 h-5" />
                </button>
              )}
              <button 
                onClick={handleCopy}
                className="p-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl backdrop-blur-xl border border-white/10 transition-all hover:scale-110 active:scale-95 shadow-2xl"
                title="Copy Reference"
              >
                {copied ? <Check className="w-5 h-5 text-emerald-400" /> : <Copy className="w-5 h-5" />}
              </button>
              <button 
                onClick={() => window.open(displayUrl, '_blank')}
                className="p-4 bg-white/10 hover:bg-white/20 text-white rounded-2xl backdrop-blur-xl border border-white/10 transition-all hover:scale-110 active:scale-95 shadow-2xl"
                title="Full Nexus View"
              >
                <ExternalLink className="w-5 h-5" />
              </button>
              <button 
                onClick={() => { if(confirm('Purge snap from nexus?')) onDelete(); }}
                className="p-4 bg-red-500/20 hover:bg-red-500/40 text-red-400 rounded-2xl backdrop-blur-xl border border-red-500/20 transition-all hover:scale-110 active:scale-95 shadow-2xl"
                title="Delete Forever"
              >
                <Trash2 className="w-5 h-5" />
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Metadata Footer */}
      <div className="p-5 relative z-10">
        <div className="flex items-center gap-3 mb-3">
          <div className="w-8 h-8 rounded-lg bg-indigo-500/10 flex items-center justify-center text-indigo-500 border border-indigo-500/20">
            <FileText className="w-4 h-4" />
          </div>
          <div className="min-w-0 flex-1">
            <h4 className="text-sm font-black text-white truncate italic uppercase tracking-tight" title={image.name}>
              {image.name}
            </h4>
            <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest">{image.mimeType.split('/')[1] || 'Unknown'}</p>
          </div>
        </div>
        <div className="flex justify-between items-center pt-3 border-t border-white/5">
          <div className="flex flex-col">
            <span className="text-[8px] text-slate-600 font-black uppercase tracking-widest">Magnitude</span>
            <span className="text-xs font-mono font-bold text-slate-400">{formatSize(image.size)}</span>
          </div>
          <div className="flex flex-col text-right">
            <span className="text-[8px] text-slate-600 font-black uppercase tracking-widest">Observed</span>
            <span className="text-xs font-mono font-bold text-slate-400">{new Date(image.uploadedAt).toLocaleDateString()}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

