    navigator.clipboard.writeText(link);
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const downloadAllAsZip = async () => {
    if (vault.images.length === 0) return;
    setZipLoading(true);
    let successCount = 0;
    let failCount = 0;

    try {
      const zip = new JSZip();
      const folder = zip.folder("snapsave-assets");

      // Process files sequentially to avoid rate limits
      for (const img of vault.images) {
        try {
          const url = await TelegramService.getImageUrl(img.telegramFileId);
          if (!url) {
            failCount++;
            continue;
          }

          // Fetch using arrayBuffer for better JSZip compatibility
          // Note: Browser CORS restrictions may still apply depending on environment
          const response = await fetch(url, { mode: 'cors' });
          if (!response.ok) throw new Error('Network stream failed');

          const buffer = await response.arrayBuffer();
          folder?.file(img.name, buffer);
          successCount++;
        } catch (err) {
          console.error(`Failed to include asset ${img.name} in archive:`, err);
          failCount++;
        }
      }

      if (successCount === 0) {
        throw new Error('Zero assets could be retrieved from the cloud nexus.');
      }

      const content = await zip.generateAsync({ 
        type: "blob",
        compression: "DEFLATE",
        compressionOptions: { level: 6 }
      });

      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = `SnapSave_Archive_${vault.username}_${Date.now()}.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      if (failCount > 0) {
        alert(`Export Complete: ${successCount} assets secured. ${failCount} assets failed hydration due to CORS/Network constraints.`);
      }
    } catch (err: any) {
      console.error('ZIP generation failed:', err);
      alert(`ARCHIVE FAILED: ${err.message || 'Stream generation error'}`);
    } finally {
      setZipLoading(false);
    }
  };

