            className="hidden" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
          />
        </div>
      </div>

      {/* Upload Progress Overlay */}
      {uploadStatus && (
        <div className="glass-card p-6 rounded-[2rem] border-indigo-500/30 animate-in fade-in slide-in-from-top-4 duration-300 relative overflow-hidden">
          <div className="absolute inset-0 bg-indigo-500/5 animate-pulse-slow"></div>
          <div className="flex justify-between items-center mb-3 relative z-10">
            <div className="flex items-center gap-3">
