            <Network className="w-5 h-5 text-indigo-400" />
            Asset Nexus
          </h3>
          <button 
            onClick={() => { setSelectionMode(!selectionMode); setSelectedIds(new Set()); }}
            className={`px-5 py-2 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all flex items-center gap-3 ${selectionMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-lg' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300 hover:border-slate-700'}`}
          >
            {selectionMode ? <CheckSquare className="w-3.5 h-3.5" /> : <Square className="w-3.5 h-3.5" />}
            {t.selectionMode}
          </button>
        </div>

        <div className="flex items-center gap-6">
          {selectionMode && selectedIds.size > 0 && (
            <button 
              onClick={() => executeExport('selected')}
              disabled={zipLoading}
              className="px-6 py-2 bg-emerald-600/20 border border-emerald-500/40 text-emerald-400 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 hover:text-white transition-all flex items-center gap-3 animate-in fade-in slide-in-from-right-2"
            >
              {zipLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Download className="w-3.5 h-3.5" />}
