            >
              <X className="w-8 h-8" />
            </button>
            <div className="text-center space-y-10">
              <div className="relative inline-block">
                <div className="w-24 h-24 bg-indigo-600 rounded-[2rem] mx-auto flex items-center justify-center shadow-2xl shadow-indigo-600/40 animate-pulse-slow">
                  <FileArchive className="w-12 h-12 text-white" />
                </div>
                <div className="absolute -top-2 -right-2 bg-emerald-500 p-2 rounded-full border-4 border-slate-950">
                  <ShieldAlert className="w-4 h-4 text-white" />
                </div>
              </div>

              <div>
                <h3 className="text-4xl font-black text-white italic uppercase tracking-tighter mb-4 leading-none">{t.exportModalTitle}</h3>
                <p className="text-slate-500 font-medium italic text-lg leading-relaxed">Choose extraction scope to compile your binary ZIP stream.</p>
              </div>

              <div className="grid grid-cols-1 gap-6">
                <button 
                  onClick={() => executeExport('all')}
                  className="flex items-center justify-between p-8 bg-slate-900/60 border border-slate-800 rounded-[2rem] hover:border-indigo-500 hover:bg-slate-900 transition-all group active:scale-95"
                >
                  <div className="text-left">
                    <p className="text-xl font-black text-white uppercase italic tracking-tight">{t.exportAll}</p>
                    <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest mt-1">{vault.images.length} Nodes Found</p>
                  </div>
                  <Download className="w-6 h-6 text-indigo-400 group-hover:scale-125 transition-transform" />
                </button>

                <button 
                  onClick={() => { setShowExportModal(false); setSelectionMode(true); }}
                  className="flex items-center justify-between p-8 bg-slate-900/60 border border-slate-800 rounded-[2rem] hover:border-emerald-500 hover:bg-slate-900 transition-all group active:scale-95"
                >
                  <div className="text-left">
                    <p className="text-xl font-black text-white uppercase italic tracking-tight">{t.exportSelected}</p>
                    <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest mt-1">Manual node filtering</p>
                  </div>
                  <CheckSquare className="w-6 h-6 text-emerald-400 group-hover:scale-125 transition-transform" />
                </button>
              </div>

              <button 
                onClick={() => setShowExportModal(false)}
                className="text-slate-600 hover:text-slate-400 text-xs font-black uppercase tracking-[0.4em] transition-colors"
              >
                {t.cancel}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

