interface VaultDashboardProps {
  vault: Vault;
  onVaultUpdate: (vault: Vault) => void;
  onExit: () => void;
}

export const VaultDashboard: React.FC<VaultDashboardProps> = ({ vault, onVaultUpdate, onExit }) => {
  const [lang, setLang] = useState('en');
  const [uploading, setUploading] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<{ fileName: string, progress: number } | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [zipLoading, setZipLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Selection States
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = TRANSLATIONS[lang] || TRANSLATIONS.en;

  const filteredAssets = useMemo(() => {
    return vault.images.filter(img => 
      img.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      img.mimeType.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [vault.images, searchQuery]);

  const totalSize = useMemo(() => {
    const bytes = vault.images.reduce((acc, img) => acc + img.size, 0);
    return (bytes / (1024 * 1024)).toFixed(2);
  }, [vault.images]);

  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedIds(newSelected);
  };

  const selectAll = () => {
    const allFilteredIds = filteredAssets.map(a => a.id);
    setSelectedIds(new Set(allFilteredIds));
  };

  const deselectAll = () => {
    setSelectedIds(new Set());
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    try {
      const updatedImages = [...vault.images];
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.size > MAX_FILE_SIZE) {
          alert(`CRITICAL: "${file.name}" is too large. Limit: 50MB.`);
          continue;
        }
        setUploadStatus({ fileName: file.name, progress: 0 });
        try {
          const tgResult = await TelegramService.uploadFile(file, (progress) => {
            setUploadStatus({ fileName: file.name, progress: Math.round(progress) });
          });
          const newAsset: VaultImage = {
            id: Math.random().toString(36).substr(2, 9),
            name: file.name,
            size: file.size,
            mimeType: file.type || 'application/octet-stream',
            telegramFileId: tgResult.file_id,
            uploadedAt: Date.now(),
            url: URL.createObjectURL(file)
          };
          updatedImages.push(newAsset);
        } catch (uploadErr: any) {
          alert(`UPLOAD FAILED: ${uploadErr.message}`);
          break;
        }
      }
      const updatedVault = await StorageService.updateVaultImages(vault.id, updatedImages);
      onVaultUpdate(updatedVault);
    } finally {
      setUploading(false);
      setUploadStatus(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  /**
   * Robust Export Engine
   * Telegram file URLs are often protected by CORS which prevents JSZip from fetching binary data directly.
   * If ZIP fetch fails, we fall back to a "Triggered Parallel Download" which opens files individually.
   */
  const executeExport = async (mode: 'all' | 'selected') => {
    const targets = mode === 'all' 
      ? vault.images 
      : vault.images.filter(img => selectedIds.has(img.id));

    if (targets.length === 0) {
      alert("No assets identified for extraction.");
      return;
    }

    setZipLoading(true);
    setShowExportModal(false);
    let successCount = 0;
    let failCount = 0;
    const failedUrls: string[] = [];

    try {
      const zip = new JSZip();
      const folder = zip.folder("SnapSave_Vault_Export");

      for (const img of targets) {
        try {
          const url = await TelegramService.getImageUrl(img.telegramFileId);
          if (!url) { failCount++; continue; }

          // Attempting Fetch (Requires CORS support on the cloud server)
          const response = await fetch(url, { mode: 'cors' }).catch(() => null);

          if (response && response.ok) {
            const buffer = await response.arrayBuffer();
            folder?.file(img.name, buffer);
            successCount++;
          } else {
            // If fetch fails (CORS), add to parallel download queue
            failedUrls.push(url);
            failCount++;
          }
        } catch (err) {
          failCount++;
        }
      }

      // If we managed to get some files into the ZIP, generate and download it
      if (successCount > 0) {
        const content = await zip.generateAsync({ 
          type: "blob",
          compression: "DEFLATE",
          compressionOptions: { level: 6 }
        });

        const zipUrl = URL.createObjectURL(content);
        const a = document.createElement('a');
        a.href = zipUrl;
        a.download = `SnapSave_${mode.toUpperCase()}_${vault.username}_${Date.now()}.zip`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(zipUrl);
      }

      // If there were CORS failures, initiate individual downloads as fallback
      if (failedUrls.length > 0) {
        alert(t.corsWarning);
        // Delay sequential downloads to avoid browser pop-up blocking
        for (let i = 0; i < failedUrls.length; i++) {
          setTimeout(() => {
            const a = document.createElement('a');
            a.href = failedUrls[i];
            a.target = "_blank";
            a.download = targets[i].name;
            a.click();
          }, i * 400); 
        }
      }

      if (successCount === targets.length) {
        // No alert needed for perfect ZIP, the file appeared.
      } else if (successCount > 0) {
        alert(`${t.successExport}: ${successCount} files zipped. ${failedUrls.length} files downloaded individually.`);
      }

    } catch (err: any) {
      console.error('Export Engine Error:', err);
      alert(`ARCHIVE PROTOCOL FAILED: ${err.message}. Individual downloads will be attempted.`);
      // Final fallback: try opening all links if everything crashed
      for (const img of targets) {
        const url = await TelegramService.getImageUrl(img.telegramFileId);
        if (url) window.open(url, '_blank');
      }
    } finally {
      setZipLoading(false);
    }
  };

  const cycleLanguage = () => {
    const langs = Object.keys(TRANSLATIONS);
    const currentIndex = langs.indexOf(lang);
    const nextIndex = (currentIndex + 1) % langs.length;
    setLang(langs[nextIndex]);
  };

  const deleteVault = async () => {
    if (confirm('Annihilate this vault node forever?')) {
      await StorageService.deleteVault(vault.id);
      onExit();
    }
  };

  const toggleViewOnly = async () => {
    const updated = await StorageService.updateVaultSettings(vault.id, { isViewOnly: !vault.isViewOnly });
    onVaultUpdate(updated);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Header Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard icon={<Database className="w-4 h-4" />} label={t.storageUsed} value={`${totalSize} MB`} color="text-indigo-400" />
        <StatCard icon={<HardDrive className="w-4 h-4" />} label={t.remainingCap} value="Unlimited" color="text-cyan-400" pulsing />
        <StatCard icon={<Clock className="w-4 h-4" />} label={t.sessionType} value={vault.expiry === ExpiryOption.NEVER ? 'Persistent' : 'Ephemeral'} color="text-emerald-400" />
        <StatCard icon={<ShieldAlert className="w-4 h-4" />} label={t.status} value={vault.isViewOnly ? 'Read Only' : 'Full Access'} color="text-orange-400" />
      </div>

      {/* Main Command Bar */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 glass-card p-8 rounded-[2.5rem] border-white/5 bg-slate-900/40 relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 blur-[100px] pointer-events-none group-hover:bg-indigo-500/10 transition-colors" />

        <div className="relative z-10">
          <div className="flex items-center gap-4 mb-2">
            <h2 className="text-4xl font-black text-white italic tracking-tighter uppercase group-hover:text-glow transition-all">
              {vault.vaultName || t.dashboardTitle}
            </h2>
          </div>
          <p className="text-slate-500 font-mono text-sm flex items-center gap-2">
            <span className="opacity-50 text-[10px] font-black tracking-widest">NODE_ID:</span> {vault.username} 
          </p>
        </div>

        <div className="flex flex-wrap gap-4 relative z-10">
          <div className="relative group/search">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500 group-focus-within/search:text-indigo-400 transition-all" />
            <input 
