interface VaultDashboardProps {
  vault: Vault;
  onVaultUpdate: (vault: Vault) => void;
  onExit: () => void;
}

export const VaultDashboard: React.FC<VaultDashboardProps> = ({ vault, onVaultUpdate, onExit }) => {
  const [lang, setLang] = useState('en');
  const [uploading, setUploading] = useState(false);
  const [uploadStatus, setUploadStatus] = useState<{ fileName: string, progress: number } | null>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [zipLoading, setZipLoading] = useState(false);
  const [zipStatus, setZipStatus] = useState<string>('');
  const [searchQuery, setSearchQuery] = useState('');

  // Selection States
  const [selectionMode, setSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = TRANSLATIONS[lang] || TRANSLATIONS.en;

  const filteredAssets = useMemo(() => {
    return vault.images.filter(img => 
      img.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      img.mimeType.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [vault.images, searchQuery]);

  const totalSize = useMemo(() => {
    const bytes = vault.images.reduce((acc, img) => acc + img.size, 0);
    return (bytes / (1024 * 1024)).toFixed(2);
  }, [vault.images]);

  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedIds(newSelected);
  };

  const selectAll = () => {
    const allFilteredIds = filteredAssets.map(a => a.id);
    setSelectedIds(new Set(allFilteredIds));
  };

  const deselectAll = () => {
    setSelectedIds(new Set());
    setSelectionMode(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    try {
      const updatedImages = [...vault.images];
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.size > MAX_FILE_SIZE) {
          alert(`CRITICAL: "${file.name}" is too large. Limit: 50MB.`);
          continue;
        }
        setUploadStatus({ fileName: file.name, progress: 0 });
        try {
          const tgResult = await TelegramService.uploadFile(file, (progress) => {
            setUploadStatus({ fileName: file.name, progress: Math.round(progress) });
          });
          const newAsset: VaultImage = {
            id: Math.random().toString(36).substr(2, 9),
            name: file.name,
            size: file.size,
            mimeType: file.type || 'application/octet-stream',
            telegramFileId: tgResult.file_id,
            uploadedAt: Date.now(),
            url: URL.createObjectURL(file)
          };
          updatedImages.push(newAsset);
        } catch (uploadErr: any) {
          alert(`UPLOAD FAILED: ${uploadErr.message}`);
          break;
        }
      }
      const updatedVault = await StorageService.updateVaultImages(vault.id, updatedImages);
      onVaultUpdate(updatedVault);
    } finally {
      setUploading(false);
      setUploadStatus(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  /**
   * PURE ZIP EXPORT ENGINE
   * Solves CORS issues using a public proxy and compiles all assets into a SINGLE ZIP archive.
   */
  const executeExport = async (mode: 'all' | 'selected') => {
    const targets = mode === 'all' 
      ? vault.images 
      : vault.images.filter(img => selectedIds.has(img.id));

    if (targets.length === 0) return;

    setZipLoading(true);
    setShowExportModal(false);
    let successCount = 0;
    let failCount = 0;

    try {
      const zip = new JSZip();
      const folder = zip.folder("SnapSave_Export");

      for (let i = 0; i < targets.length; i++) {
        const img = targets[i];
        setZipStatus(`${t.processing}: ${img.name} (${i + 1}/${targets.length})`);

        try {
          const rawUrl = await TelegramService.getImageUrl(img.telegramFileId);
          if (!rawUrl) throw new Error("Link broken");

          // Use a CORS proxy to bypass Telegram's security headers for browser-side ZIP compilation
          const proxiedUrl = `https://corsproxy.io/?${encodeURIComponent(rawUrl)}`;

          const response = await fetch(proxiedUrl);
          if (!response.ok) throw new Error("Proxy rejection");

          const blob = await response.blob();
          folder?.file(img.name, blob);
          successCount++;
        } catch (err) {
          console.error(`Shard extraction failed: ${img.name}`, err);
          failCount++;
        }
      }

      if (successCount === 0) {
        throw new Error('All shards failed hydration. Access to cloud nexus restricted.');
      }

      setZipStatus(t.compiling);
      const content = await zip.generateAsync({ 
        type: "blob",
        compression: "DEFLATE",
        compressionOptions: { level: 6 }
      });

      const url = URL.createObjectURL(content);
      const a = document.createElement('a');
      a.href = url;
      a.download = `SnapSave_${mode.toUpperCase()}_${vault.username}_${Date.now()}.zip`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      if (failCount > 0) {
        alert(`${t.successExport}: ${successCount} files secured. ${failCount} files were inaccessible.`);
      }
    } catch (err: any) {
      alert(`ARCHIVE PROTOCOL FAILED: ${err.message}`);
    } finally {
      setZipLoading(false);
      setZipStatus('');
    }
  };

  const cycleLanguage = () => {
    const langs = Object.keys(TRANSLATIONS);
    const currentIndex = langs.indexOf(lang);
    setLang(langs[(currentIndex + 1) % langs.length]);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      {/* Stats Cluster */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <StatCard icon={<Database className="w-4 h-4" />} label={t.storageUsed} value={`${totalSize} MB`} color="text-indigo-400" />
        <StatCard icon={<HardDrive className="w-4 h-4" />} label={t.remainingCap} value="Unlimited" color="text-cyan-400" pulsing />
        <StatCard icon={<Clock className="w-4 h-4" />} label={t.sessionType} value={vault.expiry === ExpiryOption.NEVER ? 'Persistent' : 'Ephemeral'} color="text-emerald-400" />
        <StatCard icon={<ShieldAlert className="w-4 h-4" />} label={t.status} value={vault.isViewOnly ? 'Read Only' : 'Full Access'} color="text-orange-400" />
      </div>

      {/* Main Control Interface */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 glass-card p-8 rounded-[2.5rem] border-white/5 bg-slate-900/40 relative overflow-hidden">
        <div className="relative z-10">
          <h2 className="text-4xl font-black text-white italic tracking-tighter uppercase mb-1">
            {vault.vaultName || t.dashboardTitle}
          </h2>
          <p className="text-slate-500 font-mono text-[10px] tracking-widest uppercase">NODE_LINK: {vault.username}</p>
        </div>

        <div className="flex flex-wrap gap-4 relative z-10">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-500" />
            <input 
              type="text"
              placeholder={t.searchPlaceholder}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="bg-slate-950/50 border border-slate-800 rounded-2xl pl-12 pr-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500/30 w-full sm:w-64 text-white"
            />
          </div>

          <button 
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            className="flex items-center gap-3 px-8 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black italic uppercase tracking-widest shadow-xl transition-all disabled:opacity-50"
          >
            {uploading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Upload className="w-5 h-5" />}
            {t.injectImages}
          </button>

          <button 
            onClick={cycleLanguage}
            className="p-3 bg-slate-800/50 border border-slate-700 rounded-2xl text-slate-400 hover:text-indigo-400 transition-all flex items-center gap-2"
          >
            <Languages className="w-5 h-5" />
            <span className="text-[10px] font-black uppercase">{lang}</span>
          </button>

          <button 
            onClick={() => setShowSettings(!showSettings)}
            className={`p-3 rounded-2xl border transition-all ${showSettings ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-400'}`}
          >
            <Settings className="w-5 h-5" />
          </button>

          <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={handleFileUpload} />
        </div>
      </div>

      {/* Action Progress Overlay */}
      {(uploadStatus || zipLoading) && (
        <div className="glass-card p-6 rounded-[2rem] border-indigo-500/30 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex justify-between items-center mb-3">
            <div className="flex items-center gap-3">
              <Loader2 className="w-4 h-4 text-indigo-400 animate-spin" />
              <span className="text-sm font-black text-white italic">
                {zipLoading ? zipStatus : uploadStatus?.fileName}
              </span>
            </div>
            {uploadStatus && <span className="text-lg font-mono font-black text-indigo-400">{uploadStatus.progress}%</span>}
          </div>
          <div className="w-full h-1.5 bg-slate-950 rounded-full overflow-hidden">
            <div 
              className={`h-full bg-indigo-600 transition-all duration-300 ${zipLoading ? 'animate-pulse' : ''}`} 
              style={{ width: zipLoading ? '100%' : `${uploadStatus?.progress}%` }} 
            />
          </div>
        </div>
      )}

      {/* Asset Grid Actions */}
      <div className="flex items-center justify-between border-b border-white/5 pb-4">
        <div className="flex items-center gap-6">
          <h3 className="text-2xl font-black text-white italic uppercase tracking-tighter flex items-center gap-3">
            <Network className="w-5 h-5 text-indigo-400" />
            Asset Nexus
          </h3>
          <button 
            onClick={() => { setSelectionMode(!selectionMode); setSelectedIds(new Set()); }}
            className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border transition-all flex items-center gap-2 ${selectionMode ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-900 border-slate-800 text-slate-500 hover:text-slate-300'}`}
          >
            <ListFilter className="w-3.5 h-3.5" />
            {t.selectionMode}
          </button>
        </div>

        <div className="flex items-center gap-4">
          {selectionMode && selectedIds.size > 0 && (
            <button 
              onClick={() => executeExport('selected')}
              disabled={zipLoading}
              className="px-6 py-2 bg-emerald-600/20 border border-emerald-500/40 text-emerald-400 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-emerald-600 hover:text-white transition-all flex items-center gap-3"
            >
              {zipLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Download className="w-3.5 h-3.5" />}
              {t.downloadSelected} ({selectedIds.size})
            </button>
          )}
          <button 
            onClick={() => setShowExportModal(true)} 
            disabled={zipLoading || vault.images.length === 0} 
            className="text-xs font-black uppercase tracking-widest text-indigo-400 hover:text-white transition-all flex items-center gap-2"
          >
            <FileArchive className="w-4 h-4" /> {t.bulkExport}
          </button>
        </div>
      </div>

      {/* Asset Grid */}
      {filteredAssets.length === 0 ? (
        <div className="py-32 text-center glass-card rounded-[3rem] border-dashed border-slate-800">
          <ImageIcon className="w-12 h-12 text-slate-800 mx-auto mb-4" />
          <p className="text-slate-500 font-bold uppercase tracking-widest">{t.emptyVault}</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
          {filteredAssets.map((img) => (
            <div key={img.id} className="relative group/wrap">
              {selectionMode && (
                <div 
                  className="absolute top-4 left-4 z-30 cursor-pointer"
                  onClick={() => toggleSelection(img.id)}
                >
                  {selectedIds.has(img.id) ? (
                    <div className="bg-indigo-600 p-2 rounded-xl border border-white/20"><Check className="w-4 h-4 text-white" /></div>
                  ) : (
                    <div className="bg-slate-900/80 p-2 rounded-xl border border-white/10 hover:border-indigo-500/50"><div className="w-4 h-4" /></div>
                  )}
                </div>
              )}
              <div className={selectionMode ? 'pointer-events-none opacity-80 scale-95 transition-all' : 'transition-all'}>
                <ImageCard 
                  image={img} 
                  isViewOnly={vault.isViewOnly} 
                  onDelete={async () => {
                    if(!confirm('Annihilate shard?')) return;
                    const updated = vault.images.filter(i => i.id !== img.id);
                    const v = await StorageService.updateVaultImages(vault.id, updated);
                    onVaultUpdate(v);
                  }} 
                />
              </div>
              {selectionMode && (
                <div className="absolute inset-0 z-20 cursor-pointer" onClick={() => toggleSelection(img.id)} />
              )}
            </div>
          ))}
        </div>
      )}

      {/* ZIP Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-950/90 backdrop-blur-2xl animate-in fade-in duration-300">
          <div className="glass-card w-full max-w-lg p-10 rounded-[4rem] border-white/10 relative text-center">
            <button onClick={() => setShowExportModal(false)} className="absolute top-8 right-8 text-slate-500 hover:text-white"><X /></button>
            <div className="w-20 h-20 bg-indigo-600 rounded-3xl mx-auto flex items-center justify-center mb-8 shadow-2xl shadow-indigo-600/40">
              <FileArchive className="w-10 h-10 text-white" />
            </div>
            <h3 className="text-3xl font-black text-white italic uppercase tracking-tighter mb-4">{t.exportModalTitle}</h3>
            <p className="text-slate-500 mb-10 italic">Single ZIP compression protocol enabled. Choose extraction depth.</p>

            <div className="grid grid-cols-1 gap-4">
              <button 
                onClick={() => executeExport('all')}
                className="flex items-center justify-between p-6 bg-slate-900 border border-slate-800 rounded-2xl hover:border-indigo-500 transition-all group"
              >
                <div className="text-left">
                  <p className="font-black text-white uppercase italic">{t.exportAll}</p>
                  <p className="text-[10px] text-slate-600">{vault.images.length} Objects</p>
                </div>
                <Download className="text-indigo-400 group-hover:scale-125 transition-transform" />
              </button>
              <button 
                onClick={() => { setShowExportModal(false); setSelectionMode(true); }}
                className="flex items-center justify-between p-6 bg-slate-900 border border-slate-800 rounded-2xl hover:border-emerald-500 transition-all group"
              >
                <div className="text-left">
                  <p className="font-black text-white uppercase italic">{t.exportSelected}</p>
                  <p className="text-[10px] text-slate-600">Manual Filtering</p>
                </div>
                <CheckSquare className="text-emerald-400 group-hover:scale-125 transition-transform" />
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

