  }, [vault.images]);

  const toggleSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedIds(newSelected);
  };

  const selectAll = () => {
    const allFilteredIds = filteredAssets.map(a => a.id);
    setSelectedIds(new Set(allFilteredIds));
  };

  const deselectAll = () => {
    setSelectedIds(new Set());
    setSelectionMode(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setUploading(true);
    try {
      const updatedImages = [...vault.images];
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        if (file.size > MAX_FILE_SIZE) {
          alert(`CRITICAL: "${file.name}" is too large. Limit: 50MB.`);
          continue;
        }
        setUploadStatus({ fileName: file.name, progress: 0 });
        try {
          const tgResult = await TelegramService.uploadFile(file, (progress) => {
            setUploadStatus({ fileName: file.name, progress: Math.round(progress) });
          });
          const newAsset: VaultImage = {
            id: Math.random().toString(36).substr(2, 9),
            name: file.name,
            size: file.size,
            mimeType: file.type || 'application/octet-stream',
            telegramFileId: tgResult.file_id,
            uploadedAt: Date.now(),
            url: URL.createObjectURL(file)
          };
          updatedImages.push(newAsset);
        } catch (uploadErr: any) {
          alert(`UPLOAD FAILED: ${uploadErr.message}`);
          break;
        }
      }
      const updatedVault = await StorageService.updateVaultImages(vault.id, updatedImages);
      onVaultUpdate(updatedVault);
    } finally {
      setUploading(false);
      setUploadStatus(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  /**
   * ROBUST ZIP EXPORT ENGINE
   * Fixes the "not downloading" issue by ensuring the binary stream is correctly captured
   * and the anchor tag trigger is executed in a mobile-compatible way.
   */
  const executeExport = async (mode: 'all' | 'selected') => {
    const targets = mode === 'all' 
      ? vault.images 
      : vault.images.filter(img => selectedIds.has(img.id));

    if (targets.length === 0) {
      alert("No targets selected for archive.");
      return;
    }

    setZipLoading(true);
    setShowExportModal(false);
    let successCount = 0;
    let failCount = 0;

    try {
      const zip = new JSZip();
      const folder = zip.folder(`SnapSave_${vault.username}_Archive`);

      for (let i = 0; i < targets.length; i++) {
        const img = targets[i];
        setZipStatus(`${t.processing}: ${img.name.slice(0, 15)}... (${i + 1}/${targets.length})`);

        try {
          const rawUrl = await TelegramService.getImageUrl(img.telegramFileId);
          if (!rawUrl) throw new Error("Cloud link resolution failed");

          // Use a more resilient proxy strategy
          // We use arrayBuffer for absolute binary safety with JSZip
          const proxiedUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(rawUrl)}`;

          const response = await fetch(proxiedUrl);
          if (!response.ok) throw new Error(`Proxy fetch failed: ${response.status}`);

          const data = await response.arrayBuffer();
          folder?.file(img.name, data, { binary: true });
          successCount++;
        } catch (err) {
          console.error(`Shard hydration failure: ${img.name}`, err);
          failCount++;
        }
      }

      if (successCount === 0) {
        throw new Error('Zero assets were successfully retrieved from the cloud nexus.');
      }

      setZipStatus(t.saving);

      // Generate ZIP blob
      const content = await zip.generateAsync({ 
        type: "blob",
        compression: "DEFLATE",
        compressionOptions: { level: 6 },
        mimeType: "application/zip"
      });

      // Execute Download Protocol
      const zipName = `SnapSave_${mode.toUpperCase()}_${vault.username}_${new Date().toISOString().split('T')[0]}.zip`;
      const url = window.URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = url;
      link.download = zipName;

      // Append to body for certain mobile browser compatibility
      document.body.appendChild(link);
      link.click();

      // Cleanup with slight delay to ensure click handles
      setTimeout(() => {
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
      }, 200);

      if (failCount > 0) {
        alert(`${t.successExport}: ${successCount} files secured. ${failCount} files failed.`);
      }
    } catch (err: any) {
      console.error('CRITICAL ARCHIVE ERROR:', err);
      alert(`ARCHIVE PROTOCOL FAILED: ${err.message}`);
    } finally {
      setZipLoading(false);
      setZipStatus('');
    }
  };

  const cycleLanguage = () => {
